// Dados do pagamento/proposta
const p = $('Get many rows').first().json || {};

// Dados do cadastro do cliente
const cadCli = $('Get many cad cli').first().json || {};

// Token C6 vindo do node anterior Token-E3
const tokenC6 = $json.access_token || $json.token || $json.accessToken || null;

function toNumberBR(value) {
  if (value === null || value === undefined || value === "") return null;

  if (typeof value === "number") return value;

  const text = String(value)
    .trim()
    .replace("R$", "")
    .replace(/\s/g, "");

  // Converte "2.297,44" para 2297.44
  if (text.includes(",")) {
    return Number(text.replace(/\./g, "").replace(",", "."));
  }

  const n = Number(text);
  return Number.isFinite(n) ? n : null;
}

// Remove acentos, caracteres estranhos e limita texto
function limparTextoC6(value, limite = 40) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")   // remove acentos
    .replace(/[^a-zA-Z0-9\s]/g, " ")  // remove pontuação/caracteres especiais
    .replace(/\s+/g, " ")             // remove espaços duplicados
    .trim()
    .substring(0, limite)
    .trim();
}

// Limpa texto simples, tratando "null" como vazio
function limparTextoBasico(value) {
  if (value === null || value === undefined) return "";

  const text = String(value).trim();

  if (
    text === "" ||
    text.toLowerCase() === "null" ||
    text.toLowerCase() === "undefined" ||
    text === "-"
  ) {
    return "";
  }

  return text;
}

// Valida e normaliza e-mail
function limparEmail(value) {
  const email = limparTextoBasico(value).toLowerCase();

  if (!email) return "";

  const regexEmail = /^[a-z0-9.!#$&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$/;

  return regexEmail.test(email) ? email : "";
}

// Normaliza nome do pagador para o C6
function normalizarNomePagador(value) {
  let nome = String(value || "").trim();

  // Se vier algo como "19.186.093 JACKSON SAMUEL XAVIER DOS SANTOS",
  // remove números/documentos do começo e mantém apenas o nome.
  nome = nome.replace(/^[\d.\-/\s]+/, "").trim();

  // Limite oficial do erro C6: payer.name máximo 40 caracteres
  nome = limparTextoC6(nome, 40);

  return nome || "Cliente";
}

